import{_ as t,H as r,f as o,i as d}from"./chunks/framework.CBmkDW73.js";const h=JSON.parse('{"title":"Spec Reviewers Gate","description":"","frontmatter":{},"headers":[],"relativePath":"skills/reviewers.md","filePath":"en/skills/reviewers.md"}'),s={name:"skills/reviewers.md"};function a(i,e,n,c,l,p){return r(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="spec-reviewers-gate" tabindex="-1">Spec Reviewers Gate <a class="header-anchor" href="#spec-reviewers-gate" aria-label="Permalink to &quot;Spec Reviewers Gate&quot;">​</a></h1><p>The Spec Reviewers protocol (<code>skills/references/reviewers.md</code>) governs the parallel review gate executed during <code>design</code> after a staging spec exists on disk and before handing off to <code>plan</code>.</p><h2 id="trigger-based-selection" tabindex="-1">Trigger-Based Selection <a class="header-anchor" href="#trigger-based-selection" aria-label="Permalink to &quot;Trigger-Based Selection&quot;">​</a></h2><p>Run every reviewer whose trigger condition matches the spec. Conditions are additive — if only baseline trigger 1 fires, only <code>spec-compliance</code> runs.</p><table tabindex="0"><thead><tr><th>#</th><th>Trigger Condition</th><th>Reviewer</th><th>Model Tier</th><th>Charter</th></tr></thead><tbody><tr><td>1</td><td><strong>Always</strong> (baseline)</td><td><code>spec-compliance</code></td><td><code>balanced</code></td><td>Verify every <code>contract:</code>/<code>invariant:</code> has an acceptance <code>test:</code>, failure modes are defined, scope boundaries are explicit, and data shapes are concrete.</td></tr><tr><td>2</td><td>Spec defines <strong>≥3 state enums or state machines</strong></td><td><code>state-machine</code></td><td><code>strongest</code></td><td>Enumerate every legal state transition; flag missing edges, dead/unreachable states, and unstated initial/terminal states.</td></tr><tr><td>3</td><td>Spec contains <strong>≥2 rules cross-referencing the same behavior</strong></td><td><code>consistency</code></td><td><code>strongest</code></td><td>Detect contradictions, undefined rule priority, incomplete exception lists, and text-vs-table discrepancies.</td></tr><tr><td>4</td><td><strong><code>topology=multi-module</code> or shared contracts</strong></td><td><code>boundary</code></td><td><code>balanced</code></td><td>Verify single shared-contract owner, explicit versioning rules, serialization compatibility, and cross-module assumptions.</td></tr><tr><td>5</td><td>Spec involves <strong>durable writes, external side effects, or commit semantics</strong></td><td><code>safety</code></td><td><code>strongest</code></td><td>Trace every write path; check crash-recovery gaps, overlapping writes, partial-commit behavior, and atomicity boundaries.</td></tr><tr><td>6</td><td><strong><code>scope=complex</code> or expects parallel/subagent execution</strong></td><td><code>implementability</code></td><td><code>balanced</code></td><td>Read as a fresh implementer; flag undefined data structures, ambiguous ordering, unspecified error handling, and missing optional/default semantics.</td></tr></tbody></table><p>Resolution order for reviewer tiers: project <code>.praxis/model-tiers.yaml</code> → user <code>~/.praxis/model-tiers.yaml</code> → harness default model (<code>tiers.&lt;tier&gt;.model</code>).</p><h2 id="parallel-execution-coordinator-synthesis" tabindex="-1">Parallel Execution &amp; Coordinator Synthesis <a class="header-anchor" href="#parallel-execution-coordinator-synthesis" aria-label="Permalink to &quot;Parallel Execution &amp; Coordinator Synthesis&quot;">​</a></h2><ol><li><strong>Parallel Dispatch</strong>: Each triggered reviewer runs as an independent subagent given the spec path (<code>docs/staging/specs/YYYY-MM-DD-&lt;topic&gt;.md</code>) and returns one finding per line (<code>BLOCK | GAP | CONFLICT</code>).</li><li><strong>Coordinator Synthesis</strong>: Runs once. The coordinator evaluates each finding critically, resolves conflicts, spots gaps between charters, judges severity (<code>BLOCK</code> vs <code>DEFER</code> with reason), patches the spec in one pass, and reports findings to the user. Reviewers advise; the coordinator decides.</li></ol>',8)])])}const u=t(s,[["render",a]]);export{h as __pageData,u as default};
